pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _val) internal {
        vm.assume(_val != 0);
        try c.SetMinSum(_val) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        assertTrue(afterFirst == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
